#include <string>
#include <stdexcept>
std::string archive_name_html(const std::string& name) {
    if (name.size() > 512) throw std::invalid_argument("name");
    std::string output = "<li>";
    for (char ch : name) {
        switch (ch) {
            case '&': output += "&amp;"; break;
            case '<': output += "&lt;"; break;
            case '>': output += "&gt;"; break;
            default: output += ch;
        }
    }
    output += "</li>";
    return output;
}

